// The remark shared by the seven thalamic clusters.
const cluster = (name, approx) => `One of the seven clusters of Najdenovska et al. (2018), found by grouping the voxels of the thalamus by their local diffusion properties, and named “${name}” in TemplateFlow’s table. It ${approx}; the correspondence between a diffusion cluster and the nuclei of histology is approximate.`;

// The remark shared by the hippocampal subfields of MASSP 2.0.
const SUBFIELD = 'A subfield of MASSP 2.0, delineated on the 7 T images of the AHEAD database (Alkemade et al. 2020; Bazin et al. 2020). At this resolution the borders between the fields of the hippocampus are approximate.';

